#!/usr/bin/env python3
"""Render gc-generations.drawio -> ../images/gc-generations.pdf (generated by ch3-figures_gen.py)."""
import importlib.util, os
spec = importlib.util.spec_from_file_location("ch3gen", os.path.join(os.path.dirname(os.path.abspath(__file__)), "ch3-figures_gen.py"))
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
m.gc_generations()
